@gene('Z26a', 'cache the goal field and enemy-champion danger zone once per turn; retreat home to heal when hurt (with hysteresis)', parents=['s4'])
def update() -> None:
    hf = me().health_frac
    if hf < 0.35:
        HEAL = True
    if hf > 0.9:
        HEAL = False
    GF = goal_field(HEAL)
    DANGER = Tiles()
    for u in enemies():
        if u.is_champion:
            DANGER = DANGER | near(u.pos, 2)

@gene('s4', 'how much closer a step brings me to the goals (cached field); 0 when unreachable or when hurt and stepping near an enemy champion; penalized when stepping near an enemy champion', parents=['s4'])
